@startuml

class Researcher {}

class SeniorResearcher extends Researcher {}

class JuniorResearcher extends Researcher {}

class Team {
  + task : string
}

class Area {
  + name : string
}

class Project {
  + name : string
}

class AreaManager {}

Area "1" -- "1" AreaManager : managed by
Area "1" -- "1..*" Team : contains
Team "1" -- "1" SeniorResearcher : led by
Team "1" -- "1..*" JuniorResearcher : includes
Team "1" -- "0..1" Project : carries out
Project "1" -- "1" Area : assigned to

@enduml

